// Mode: Run Once for All Items
const item0 = ($input.all()[0] || { json: {} }).json;
const raw = item0.message ?? item0.text ?? item0?.choices?.[0]?.message?.content?.message ?? '';

function cleanTextButKeepUrls(s) {
  let text = String(s);

  // Чистим текст ОТ проблемных символов
  text = text
    // Заменяем все проблемные кавычки на обычные
    .replace(/['']/g, "'")
    .replace(/[""]/g, '"')
    .replace(/[«»]/g, '"')
    // Удаляем эмодзи
    .replace(/[\u{1F300}-\u{1FAFF}]/gu, '')
    .replace(/[\u{2600}-\u{27BF}]/gu, '')
    // Нормализуем переносы
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    // Убираем невидимые символы
    .replace(/[\u0000-\u001F\u007F-\u009F]/g, '')
    .replace(/[\u200B-\u200F]/g, '')
    .replace(/[\u202A-\u202E]/g, '')
    .replace(/[\u2060-\u206F]/g, '')
    .replace(/\uFEFF/g, '')
    // Заменяем спецсимболы
    .replace(/\u00A0/g, ' ')
    .replace(/\u00AD/g, '')
    .replace(/—/g, ' - ')
    .replace(/–/g, ' - ')
    // Убираем множественные переносы
    .replace(/\n{3,}/g, '\n\n');

  // Оборачиваем каждую ссылку в пробелы и убираем всё после ?
  text = text.replace(/(https?:\/\/[^\s"'«»?]+)(\?[^\s"'«»]*)?/gi, (match, base, params) => {
    return ' ' + base + ' ';
  });

  // Убираем множественные пробелы
  text = text.replace(/[ \t]+/g, ' ').trim();

  return text;
}

let text = cleanTextButKeepUrls(raw);

// ДИАГНОСТИКА: выводим что на байте 308
console.log('=== ДИАГНОСТИКА ===');
console.log('Длина текста:', text.length);
console.log('Байты 300-320:', Buffer.from(text.slice(300, 320)).toString('hex'));
console.log('Текст 300-320:', text.slice(300, 320));
console.log('Символы 300-320:', text.slice(300, 320).split('').map((c, i) => `${300+i}: ${c} (${c.charCodeAt(0)})`).join('\n'));

// Чанкинг
const SAFE = 4000;
const messages = [];
let i = 0;

while (i < text.length) {
  let end = Math.min(i + SAFE, text.length);

  if (end < text.length) {
    let cut = text.lastIndexOf('\n', end);
    if (cut <= i) cut = text.lastIndexOf(' ', end);
    if (cut > i) end = cut;
  }

  const chunk = text.slice(i, end).trim();

  if (chunk) {
    messages.push({ json: { text: chunk } });
  }

  i = end + 1;
}

return messages.length ? messages : [{ json: { text: '' } }];

